type TerminalColors = {
  readonly fg: string
}

export const Terminal = (props: { readonly label: string }) => {
  const getTerminalColors = (): TerminalColors => ({ fg: getComputedStyle(document.body).color })
  const colors = getTerminalColors()
  return (
    <>
      <div style={{ color: colors.fg }}>{props.label}</div>
    </>
  )
}

export const tint = (colors: TerminalColors): string => colors.fg

export type SessionReviewProps = { readonly label: string }

type SessionReviewSelection = { readonly start: number; readonly end: number }

export const SessionReview = (props: SessionReviewProps) => {
  const selection: SessionReviewSelection = { start: 0, end: getComputedStyle(document.body).color.length }
  return <div style={{ color: String(selection.end) }}>{props.label}</div>
}

export const width = (selection: SessionReviewSelection): number => selection.end - selection.start

type Highlight = { readonly text: string }

export function showWhatsNew(items: readonly string[]) {
  const highlights: Highlight[] = items.map((text) => ({ text }))
  void getComputedStyle(document.body)
  void highlights
}

export const label = (highlight: Highlight): string => highlight.text
